import Foundation

enum XYProjectSeedError: LocalizedError {
    case invalidEmbeddedSeed

    var errorDescription: String? {
        switch self {
        case .invalidEmbeddedSeed:
            return "Embedded OP-XY project seed could not be decoded."
        }
    }
}

enum XYProjectSeed {
    static func data() throws -> [UInt8] {
        guard let data = Data(base64Encoded: encodedProjectBase64, options: .ignoreUnknownCharacters) else {
            throw XYProjectSeedError.invalidEmbeddedSeed
        }
        return [UInt8](data)
    }

    // Minimal Track 11 MIDI project seed generated from local OP-XY format research.
    // Runtime export rewrites notes, locks, tempo, groove, and pattern length.
    private static let encodedProjectBase64 = """

"""
}
